def transpose_two_strings(str1: str, str2: str) -> str:
    lines = []
    max_len = max(len(str1), len(str2))
    for i in range(max_len):
        c1 = str1[i] if i < len(str1) else ' '
        c2 = str2[i] if i < len(str2) else ' '
        lines.append(f"{c1} {c2}")
    return '\n'.join(lines)
